"""Render rows of strings as a GitHub markdown table."""


def _line(cells):
    return "| " + " | ".join(cells) + " |"


def to_markdown(rows):
    """rows is a list of lists of strings; the first row is the header.

    Cells are stripped and any `|` is escaped as `\\|`. Raises ValueError for
    no rows, an empty header, or a row whose length differs from the header.
    """
    if not rows:
        raise ValueError("no rows")
    if not rows[0]:
        raise ValueError("empty header")
    width = len(rows[0])
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(f"row {i + 1} has {len(row)} cells, expected {width}")
    cells = [[c.strip().replace("|", "\\|") for c in row] for row in rows]
    lines = [_line(cells[0]), _line(["---"] * width)]
    lines += [_line(row) for row in cells[1:]]
    return "\n".join(lines)

